-- SIMBAR application schema from the Hostinger backup of 9 November 2026.

-- Timestamps retain their original wall-clock values.

CREATE SCHEMA simbar;

REVOKE ALL ON SCHEMA simbar FROM PUBLIC, anon, authenticated, service_role;

CREATE TABLE simbar."categories" (
    "id" bigint generated by default as identity primary key not null,
    "name" varchar not null,
    "description" text,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
);

CREATE TABLE simbar."kategori_aset" (
    "id" bigint generated by default as identity primary key not null,
    "nama_kategori" varchar not null,
    "deskripsi" text,
    "is_active" boolean not null default true,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "kode_golongan" varchar,
    "golongan" varchar check ("golongan" in ('tanah', 'peralatan_mesin', 'gedung_bangunan', 'jalan_irigasi', 'aset_tetap_lainnya', 'kdp')) not null default 'peralatan_mesin',
    "umur_manfaat" integer not null default '5',
    "dapat_disusutkan" boolean not null default true
);

CREATE TABLE simbar."ruangan" (
    "id" bigint generated by default as identity primary key not null,
    "nama_ruangan" varchar not null,
    "lokasi" varchar,
    "keterangan" text,
    "is_active" boolean not null default true,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    is_migration_placeholder boolean not null default false
);

CREATE TABLE simbar."units" (
    "id" bigint generated by default as identity primary key not null,
    "name" varchar not null,
    "symbol" varchar not null,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
);

CREATE TABLE simbar."users" (
    "id" bigint generated by default as identity primary key not null,
    "name" varchar not null,
    "email" varchar not null,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "phone" varchar,
    "is_approved" boolean not null default false,
    "approved_at" timestamp without time zone,
    "approved_by" bigint,
    "role" varchar not null default 'staff',
    "last_login_at" timestamp without time zone,
    "last_activity_at" timestamp without time zone,
    "last_ip_address" varchar,
    auth_user_id uuid unique
);

CREATE TABLE simbar."barang_aset" (
    "id" bigint generated by default as identity primary key not null,
    "kode_aset" varchar not null,
    "nama_aset" varchar not null,
    "kategori_aset_id" bigint not null,
    "ruangan_id" bigint not null,
    "kondisi" varchar check ("kondisi" in ('baik', 'rusak_ringan', 'rusak_berat')) not null default 'baik',
    "tanggal_masuk" date not null,
    "jumlah" integer not null default '1',
    "harga_perolehan" numeric,
    "merk" varchar,
    "spesifikasi" varchar,
    "foto" varchar,
    "keterangan" text,
    "butuh_perbaikan" boolean not null default false,
    "created_by" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "tahun_perolehan" integer,
    "sumber_dana" varchar,
    "nomor_register" varchar,
    "umur_manfaat_override" integer,
    "nilai_residu" numeric not null default '0',
    "nilai_penambahan" numeric not null default '0',
    "nilai_pengurangan" numeric not null default '0',
    "nilai_koreksi" numeric not null default '0',
    "status_aset" varchar check ("status_aset" in ('aktif', 'tidak_aktif', 'dihapuskan', 'dipindahkan')) not null default 'aktif',
    "tanggal_penghapusan" date,
    "alasan_penghapusan" text,
    "no_sertifikat" varchar,
    "asal_perolehan" varchar,
    "ukuran_konstruksi" varchar,
    foreign key("kategori_aset_id") references simbar."kategori_aset"("id") on delete restrict,
    foreign key("ruangan_id") references simbar."ruangan"("id") on delete restrict,
    foreign key("created_by") references simbar."users"("id") on delete set null
);

CREATE TABLE simbar."items" (
    "id" bigint generated by default as identity primary key not null,
    "category_id" bigint not null,
    "unit_id" bigint not null,
    "code" varchar not null,
    "name" varchar not null,
    "description" text,
    "stock" integer not null default '0',
    "minimum_stock" integer not null default '0',
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "photo" varchar,
    "barcode" varchar,
    "perolehan" varchar,
    "price" numeric not null default '0',
    foreign key("category_id") references simbar."categories"("id") on delete restrict,
    foreign key("unit_id") references simbar."units"("id") on delete restrict
);

CREATE TABLE simbar."login_histories" (
    "id" bigint generated by default as identity primary key not null,
    "user_id" bigint not null,
    "action" varchar check ("action" in ('login', 'logout')) not null default 'login',
    "ip_address" varchar,
    "user_agent" varchar,
    "device" varchar,
    "browser" varchar,
    "platform" varchar,
    "created_at" timestamp without time zone not null default CURRENT_TIMESTAMP,
    foreign key("user_id") references simbar."users"("id") on delete cascade
);

CREATE TABLE simbar."logs" (
    "id" bigint generated by default as identity primary key not null,
    "user_id" bigint,
    "action" varchar not null,
    "description" text,
    "created_at" timestamp without time zone not null default CURRENT_TIMESTAMP,
    foreign key("user_id") references simbar."users"("id") on delete set null
);

CREATE TABLE simbar."sbbk_documents" (
    "id" bigint generated by default as identity primary key not null,
    "nomor_sbbk" varchar not null,
    "tanggal_sbbk" date not null,
    "unit_peminta" varchar not null,
    "perihal" varchar,
    "keterangan" text,
    "file_path" varchar not null,
    "file_name" varchar not null,
    "file_mime" varchar not null,
    "file_size" integer not null,
    "uploaded_by" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("uploaded_by") references simbar."users"("id") on delete set null
);

CREATE TABLE simbar."pemeliharaan_aset" (
    "id" bigint generated by default as identity primary key not null,
    "barang_aset_id" bigint not null,
    "ruangan_id" bigint not null,
    "tanggal_pemeliharaan" date not null,
    "jenis_pemeliharaan" varchar check ("jenis_pemeliharaan" in ('rutinitas', 'perbaikan', 'penggantian')) not null default 'perbaikan',
    "deskripsi_masalah" text not null,
    "tindakan_perbaikan" text,
    "status" varchar check ("status" in ('menunggu', 'proses', 'selesai', 'rusak')) not null default 'menunggu',
    "teknisi" varchar not null,
    "biaya" numeric,
    "lampiran_foto" varchar,
    "tanggal_selesai" date,
    "catatan" text,
    "created_by" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("barang_aset_id") references simbar."barang_aset"("id") on delete cascade,
    foreign key("ruangan_id") references simbar."ruangan"("id") on delete restrict,
    foreign key("created_by") references simbar."users"("id") on delete set null
);

CREATE TABLE simbar."penyusutan_aset" (
    "id" bigint generated by default as identity primary key not null,
    "barang_aset_id" bigint not null,
    "tahun" integer not null,
    "bulan" integer,
    "tanggal_hitung" date not null,
    "nilai_perolehan" numeric not null,
    "nilai_residu" numeric not null default '0',
    "umur_manfaat" integer not null,
    "penyusutan_per_tahun" numeric not null,
    "penyusutan_per_bulan" numeric not null,
    "penyusutan_periode" numeric not null,
    "akumulasi_penyusutan_awal" numeric not null default '0',
    "akumulasi_penyusutan_akhir" numeric not null,
    "nilai_buku_awal" numeric not null,
    "nilai_buku_akhir" numeric not null,
    "mutasi_penambahan" numeric not null default '0',
    "mutasi_pengurangan" numeric not null default '0',
    "mutasi_koreksi" numeric not null default '0',
    "metode_penyusutan" varchar not null default 'garis_lurus',
    "keterangan" text,
    "created_by" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("barang_aset_id") references simbar."barang_aset"("id") on delete cascade,
    foreign key("created_by") references simbar."users"("id") on delete set null
);

CREATE TABLE simbar."permintaan_barang" (
    "id" bigint generated by default as identity primary key not null,
    "kode_permintaan" varchar not null,
    "user_id" bigint not null,
    "tipe" varchar check ("tipe" in ('barang_baru', 'restok')) not null default 'barang_baru',
    "item_id" bigint,
    "nama_barang" varchar not null,
    "ruangan_id" bigint,
    "jumlah" integer not null default '1',
    "prioritas" varchar check ("prioritas" in ('rendah', 'sedang', 'tinggi')) not null default 'sedang',
    "keterangan" text,
    "tanggal_permintaan" date not null,
    "status" varchar check ("status" in ('pending', 'diproses', 'disetujui', 'ditolak', 'revisi', 'tersedia', 'dibaca')) not null default 'pending',
    "catatan_admin" text,
    "alasan_penolakan" text,
    "permintaan_revisi" text,
    "verified_by" bigint,
    "verified_at" timestamp without time zone,
    "notified_at" timestamp without time zone,
    "created_item_id" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "foto_barang" varchar,
    "tipe_foto_barang" varchar,
    foreign key("user_id") references simbar."users"("id") on delete cascade,
    foreign key("item_id") references simbar."items"("id") on delete set null,
    foreign key("ruangan_id") references simbar."ruangan"("id") on delete set null,
    foreign key("verified_by") references simbar."users"("id") on delete set null,
    foreign key("created_item_id") references simbar."items"("id") on delete set null
);

CREATE TABLE simbar."permintaan_restok" (
    "id" bigint generated by default as identity primary key not null,
    "kode_restok" varchar not null,
    "user_id" bigint not null,
    "item_id" bigint not null,
    "jumlah_diminta" integer not null,
    "prioritas" varchar check ("prioritas" in ('rendah', 'sedang', 'tinggi')) not null default 'sedang',
    "keterangan" text,
    "tanggal_permintaan" date not null,
    "status" varchar check ("status" in ('pending', 'disetujui', 'ditolak', 'tersedia', 'dibaca')) not null default 'pending',
    "catatan_admin" text,
    "alasan_penolakan" text,
    "verified_by" bigint,
    "verified_at" timestamp without time zone,
    "notified_at" timestamp without time zone,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("user_id") references simbar."users"("id") on delete cascade,
    foreign key("item_id") references simbar."items"("id") on delete cascade,
    foreign key("verified_by") references simbar."users"("id") on delete set null
);

CREATE TABLE simbar."stock_in" (
    "id" bigint generated by default as identity primary key not null,
    "item_id" bigint not null,
    "user_id" bigint not null,
    "quantity" integer not null,
    "date" date not null,
    "notes" text,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("item_id") references simbar."items"("id") on delete cascade,
    foreign key("user_id") references simbar."users"("id") on delete restrict
);

CREATE TABLE simbar."stock_out" (
    "id" bigint generated by default as identity primary key not null,
    "item_id" bigint not null,
    "user_id" bigint not null,
    "quantity" integer not null,
    "date" date not null,
    "notes" text,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("item_id") references simbar."items"("id") on delete cascade,
    foreign key("user_id") references simbar."users"("id") on delete restrict
);

CREATE TABLE simbar."stock_out_requests" (
    "id" bigint generated by default as identity primary key not null,
    "user_id" bigint not null,
    "item_id" bigint not null,
    "quantity" integer not null,
    "notes" text,
    "status" varchar check ("status" in ('pending', 'approved', 'rejected', 'cancelled', 'completed')) not null default 'pending',
    "request_date" date not null,
    "pickup_date" date,
    "processed_by" bigint,
    "processed_at" timestamp without time zone,
    "reject_reason" text,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("user_id") references simbar."users"("id") on delete cascade,
    foreign key("item_id") references simbar."items"("id") on delete cascade,
    foreign key("processed_by") references simbar."users"("id") on delete set null
);

CREATE TABLE simbar."usulan_penerimaan_barang" (
    "id" bigint generated by default as identity primary key not null,
    "kode_usulan" varchar not null,
    "user_id" bigint not null,
    "ruangan_id" bigint not null,
    "kategori_aset_id" bigint,
    "nama_barang" varchar not null,
    "merk" varchar,
    "spesifikasi" text,
    "jumlah" integer not null default '1',
    "kondisi_barang" varchar check ("kondisi_barang" in ('baru', 'bekas_baik', 'bekas_rusak_ringan')) not null default 'baru',
    "kelengkapan" varchar check ("kelengkapan" in ('lengkap', 'tidak_lengkap')) not null default 'lengkap',
    "estimasi_harga" numeric,
    "sumber_barang" varchar,
    "foto_barang" text,
    "tanggal_usulan" date not null,
    "tanggal_penerimaan_fisik" date,
    "status" varchar check ("status" in ('pending', 'diproses', 'disetujui', 'ditolak', 'revisi')) not null default 'pending',
    "prioritas" varchar check ("prioritas" in ('rendah', 'sedang', 'tinggi')) not null default 'sedang',
    "keterangan_user" text,
    "catatan_admin" text,
    "alasan_penolakan" text,
    "permintaan_revisi" text,
    "verified_by" bigint,
    "verified_at" timestamp without time zone,
    "barang_aset_id" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    foreign key("user_id") references simbar."users"("id") on delete cascade,
    foreign key("ruangan_id") references simbar."ruangan"("id") on delete restrict,
    foreign key("kategori_aset_id") references simbar."kategori_aset"("id") on delete set null,
    foreign key("verified_by") references simbar."users"("id") on delete set null,
    foreign key("barang_aset_id") references simbar."barang_aset"("id") on delete set null
);

CREATE TABLE simbar."usulan_permintaan_barang" (
    "id" bigint generated by default as identity primary key not null,
    "kode_permintaan" varchar not null,
    "user_id" bigint not null,
    "ruangan_id" bigint not null,
    "nama_barang" varchar not null,
    "jumlah" integer not null default '1',
    "prioritas" varchar check ("prioritas" in ('rendah', 'sedang', 'tinggi')) not null default 'sedang',
    "keterangan_user" text,
    "tanggal_permintaan" date not null,
    "status" varchar check ("status" in ('pending', 'diproses', 'disetujui', 'ditolak', 'revisi')) not null default 'pending',
    "catatan_admin" text,
    "alasan_penolakan" text,
    "permintaan_revisi" text,
    "verified_by" bigint,
    "verified_at" timestamp without time zone,
    "item_id" bigint,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "foto_barang" varchar,
    "tipe_foto_barang" varchar,
    foreign key("user_id") references simbar."users"("id") on delete cascade,
    foreign key("ruangan_id") references simbar."ruangan"("id") on delete restrict,
    foreign key("verified_by") references simbar."users"("id") on delete set null,
    foreign key("item_id") references simbar."items"("id") on delete set null
);

