CREATE INDEX "pemeliharaan_aset_status_index" ON simbar."pemeliharaan_aset" ("status");

CREATE INDEX "pemeliharaan_aset_tanggal_pemeliharaan_index" ON simbar."pemeliharaan_aset" ("tanggal_pemeliharaan");

