REVOKE ALL ON ALL TABLES IN SCHEMA simbar FROM PUBLIC, anon, authenticated, service_role;

REVOKE ALL ON ALL SEQUENCES IN SCHEMA simbar FROM PUBLIC, anon, authenticated, service_role;
